      "desc": "樱花妆是日系春日感的标准答案：淡粉带微珠光的眼影、樱花粉腮红打在眼下、水光粉唇，整体透明感强，像站在樱花树下被柔光照着。它和芭比妆都用粉，但樱花妆是低饱和、高明度的淡粉，靠微珠光提亮，绝不做浓重的粉色块。新手最容易画错的是粉色选得太饱和、下手太重，眼皮立刻显肿、脸显膨胀；正确做法是挑带一点奶调或灰调的淡粉，全部少量多次，最后用高光把立体度找回来。",
